(function() {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(SutramImportProgressComponent, [{
    type: Component,
    args: [{ selector: "sutram-import-progress", changeDetection: ChangeDetectionStrategy2.OnPush, template: `<!-- sutram-import-progress.component.html -->
<p-dialog [(visible)]="visible"
          [modal]="true"
          [style]="{ width: '520px', maxWidth: '95vw' }"
          [closable]="!progress.isActive"
          header="\u0907\u092E\u094D\u092A\u094B\u0930\u094D\u091F \u092A\u094D\u0930\u0917\u0924\u093F (Import Progress)">

  <div class="py-3 text-center">

    <!-- Progress Bar -->
    <div class="mb-3 px-2">
      <div class="d-flex justify-content-between mb-1">
        <span class="small fw-bold">{{ progress.current }} / {{ progress.total }} \u092A\u0902\u0915\u094D\u0924\u093F\u092F\u093E\u0901 \u092A\u094D\u0930\u0938\u0902\u0938\u094D\u0915\u0943\u0924</span>
        <span class="small fw-bold text-primary">{{ progress.percentage }}%</span>
      </div>
      <p-progressBar [value]="progress.percentage" [showValue]="false" styleClass="sutram-progress"></p-progressBar>
    </div>

    <!-- Live Status Counters Grid -->
    <div class="row g-2 mb-3">
      <div [class]="(progress.deleted || 0) > 0 ? 'col' : 'col-3'">
        <div class="card p-2 bg-soft-success border border-success">
          <small class="text-muted d-block" style="font-size: 11px;">Inserted</small>
          <strong class="fs-5 text-success">{{ progress.inserted }}</strong>
        </div>
      </div>
      <div [class]="(progress.deleted || 0) > 0 ? 'col' : 'col-3'">
        <div class="card p-2 bg-soft-primary border border-primary">
          <small class="text-muted d-block" style="font-size: 11px;">Updated</small>
          <strong class="fs-5 text-primary">{{ progress.updated }}</strong>
        </div>
      </div>
      <div *ngIf="(progress.deleted || 0) > 0" class="col">
        <div class="card p-2 bg-soft-warning border border-warning">
          <small class="text-muted d-block" style="font-size: 11px;">Deleted</small>
          <strong class="fs-5 text-warning">{{ progress.deleted }}</strong>
        </div>
      </div>
      <div [class]="(progress.deleted || 0) > 0 ? 'col' : 'col-3'">
        <div class="card p-2 bg-soft-warning border border-warning">
          <small class="text-muted d-block" style="font-size: 11px;">Duplicate</small>
          <strong class="fs-5 text-warning">{{ progress.duplicate }}</strong>
        </div>
      </div>
      <div [class]="(progress.deleted || 0) > 0 ? 'col' : 'col-3'">
        <div class="card p-2 bg-soft-danger border border-danger">
          <small class="text-muted d-block" style="font-size: 11px;">Rejected</small>
          <strong class="fs-5 text-danger">{{ progress.rejected }}</strong>
        </div>
      </div>
    </div>

    <!-- Error Report Download Action if rejected rows exist -->
    <div *ngIf="progress.rejected > 0 && !progress.isActive" class="alert alert-danger p-2 text-start mb-2">
      <div class="d-flex align-items-center justify-content-between">
        <div>
          <strong>{{ progress.rejected }} \u092A\u0902\u0915\u094D\u0924\u093F\u092F\u093E\u0901 \u0930\u093F\u091C\u0947\u0915\u094D\u091F \u0939\u0941\u0908\u0902!</strong>
          <small class="d-block text-muted">\u0924\u094D\u0930\u0941\u091F\u093F \u0935\u093F\u0935\u0930\u0923 \u0915\u0947 \u0938\u093E\u0925 Excel \u0921\u093E\u0909\u0928\u0932\u094B\u0921 \u0915\u0930\u0947\u0902</small>
        </div>
        <button pButton
                label="Error Report (.xlsx)"
                icon="pi pi-download"
                class="p-button-sm p-button-danger"
                [loading]="isDownloadingReport"
                (click)="downloadErrorReport()">
        </button>
      </div>
    </div>

  </div>

  <ng-template pTemplate="footer">
    <div class="d-flex justify-content-end gap-2">
      <button *ngIf="progress.isActive"
              pButton
              label="\u0930\u094B\u0915\u0947\u0902 (Cancel)"
              class="p-button-outlined p-button-danger"
              (click)="cancelRequested.emit()">
      </button>
      <button *ngIf="!progress.isActive"
              pButton
              label="\u0938\u092E\u093E\u092A\u094D\u0924 (Done)"
              class="p-button-primary"
              (click)="close()">
      </button>
    </div>
  </ng-template>

</p-dialog>
`, styles: [".sutram-progress {\n  height: 12px;\n  border-radius: 6px;\n}\n"] }]
  }], function() {
    return [{ type: SutramExcelApiService }];
  }, { visible: [{
    type: Input
  }], progress: [{
    type: Input
  }], tableName: [{
    type: Input
  }], rejectedRows: [{
    type: Input
  }], visibleChange: [{
    type: Output
  }], cancelRequested: [{
    type: Output
  }] });
})();

